from PIL import Image

g = Image.open("/opt/exam/grader/golden.png")
c = Image.open("/var/exam/capture.png")

w, h = g.size
g_pix = g.load()
c_pix = c.load()

diffs = []
diff_coords = []
for y in range(h):
    for x in range(w):
        d = sum(abs(g_pix[x,y][i] - c_pix[x,y][i]) for i in range(3))
        if d > 10:
            diff_coords.append((x, y, d))

print(f"Total differing pixels: {len(diff_coords)} of {w*h} ({len(diff_coords)/(w*h)*100:.1f}%)")

# Cluster the diffs by region
regions = {"top_left": 0, "bottom_right": 0, "fixture": 0, "other": 0}
for x, y, d in diff_coords:
    if x < 100 and y < 100:
        regions["top_left"] += 1
    elif x > 300 and y > 200:
        regions["bottom_right"] += 1
    elif 150 <= x <= 350 and 100 <= y <= 250:
        regions["fixture"] += 1
    else:
        regions["other"] += 1

print("Differences by region:", regions)
'

